template <class Unit>            // Unit: tag carrying dimension + std::ratio scale
struct quantity {
    double value;
    constexpr explicit quantity(double v) : value(v) {}
};
template <class To, class From>
constexpr quantity<To> convert(quantity<From> q) {      // one place owns the factor
    return quantity<To>(q.value * From::scale / To::scale);
}
constexpr auto operator+(quantity<Length> a, quantity<Length> b) {
    return quantity<Length>(a.value + b.value);
}
